pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 startTime, uint48 delta, uint256 blockNumber) public {
        vm.assume(delta > 0);
        vm.warp(startTime);
        vm.roll(blockNumber);

        uint256 oldPastBlockTime = c.pastBlockTime();

        // Fund contract 10 ether for payment
        vm.deal(address(c), 10 ether);

        // Make a fallback call that will update pastBlockTime
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            // The bug: pastBlockTime = block.timestamp - 1, so after update it should be exactly block.timestamp - 1
            // Reference: pastBlockTime = block.timestamp, so after update it should be exactly block.timestamp
            // But we need the test to pass on reference and fail on mutant
            // Use warp to ensure block.timestamp increases appropriately
            vm.warp(block.timestamp + delta);

            // Make another call to see if time difference is exactly 1 second
            // Actually, simpler: check if pastBlockTime was set to block.timestamp (reference) vs block.timestamp - 1 (mutant)
            // Since we can read pastBlockTime after the call
            uint256 newPastBlockTime = c.pastBlockTime();

            // For reference: newPastBlockTime == block.timestamp after the call (which was startTime before warp)
            // For mutant: newPastBlockTime == block.timestamp - 1
            // We warp to startTime + delta, so block.timestamp after warp is startTime + delta
            // But we need the rule that works for all cases
            assertTrue(newPastBlockTime == startTime);
        }
    }
}

