pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockOffset) public {
        vm.assume(amount == 10 ether);
        vm.assume(blockOffset < 1000);
        // Advance to a deterministic block so we can test the condition
        vm.roll(block.number + blockOffset + 1);

        // Fund the contract with some ETH to enable transfers
        vm.deal(address(c), 100 ether);

        // Call the fallback
        (bool success, ) = address(c).call{value: amount}("");

        // Assert that if the call reverted (e.g., due to timestamp check) or succeeded,
        // the invariant holds: either the contract balance ends up 0 after transfer,
        // or the current block number is not a multiple of 15 (so transfer didn't occur).
        // Actually the property is: after a successful fallback call with exactly 10 ether,
        // the contract's balance is zero iff block.number % 15 == 0.
        // We'll check: (block.number % 15 != 0) implies address(c).balance == 100 ether (no transfer)
        // and (block.number % 15 == 0) implies address(c).balance == 0 (transfer happened).
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0, "Expected balance zero when block % 15 == 0");
        } else {
            assertTrue(address(c).balance == 100 ether, "Expected balance unchanged when block % 15 != 0");
        }
    }
}

