pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Drive the contract through a sequence of calls; we only need to check after a fallback call.
        // Use a loop with different block numbers to ensure the invariant holds.
        // We'll simulate a single fallback call with exactly 10 ether at a random block number.
        // The invariant: after the call, the contract balance is either the remaining balance after transfer (if block.number % 15 == 0, balance becomes 0; if != 0, balance increases by 10 ether).
        // More precisely: if block.number % 15 == 0, the final balance is 0 (since the transfer sends all balance to caller). 
        // But the reference C only sends the balance when block.number % 15 == 0, so after that the balance is 0.
        // If block.number % 15 != 0, no transfer occurs, so balance increases by 10 ether.
        // So we can test: after call, balance == (block.number % 15 == 0 ? 0 : (previous_balance + 10 ether)).
        // However previous_balance is unknown. Simpler: we can check that if block.number % 15 == 0, then balance == 0; otherwise balance >= 10 ether? No, that's too weak.
        // Better: track the balance before the call and compute expected.
        // But we can't read internal state. Another approach: use a sequence where we know initial balance = 0.
        // Since this is fuzz, we can assume no prior ether. Use vm.deal to set contract balance to 0 initially.
        // Then after one fallback call: if block.number % 15 == 0, balance becomes 0; else balance becomes 10 ether.
        // Actually the reference sends all balance when block.number % 15 == 0, so balance becomes 0.
        // So we can assert: after call, balance == (block.number % 15 == 0 ? 0 : 10 ether).

        // Set contract balance to 0
        vm.deal(address(c), 0);

        // Choose a block number; we can warp to set block.timestamp but not block.number directly.
        // We'll simulate by using vm.roll to set block.number.
        // seed will determine block.number.
        uint256 bn = bound(seed, 1, 10000);
        vm.roll(bn);
        // Also need a timestamp > pastBlockTime (which is 0 at start). We can keep timestamp as is.

        // Call fallback with 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success);

        uint256 balance = address(c).balance;
        bool condition = (bn % 15 == 0);
        if (condition) {
            assertTrue(balance == 0, "balance should be 0 after transfer");
        } else {
            assertTrue(balance == 10 ether, "balance should be 10 ether when no transfer");
        }
    }
}

