        // set the block context
        vm.roll(blockNumber);
        vm.warp(timestamp);

        uint256 balanceBefore = address(c).balance;

        // fund the contract with 10 ether externally so it has balance
        vm.deal(address(c), 10 ether);

        // call fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // if call succeeded, the balance should only decrease when block.number % 15 == 0
        bool balanceDecreased = balanceAfter < balanceBefore;
        bool isMultipleOf15 = (blockNumber % 15 == 0);

        assertTrue(!balanceDecreased || isMultipleOf15, "Balance decreased when block not multiple of 15");
    }
}

